// Monodromy certificate for the folded pencil {Gamma + u*Q}.
//
// The pencil is the fibre system of psi = -Gamma/Q : P^1 -> P^1 of degree n'.
// Since H = Q + T*Gamma is linear in T, H is irreducible over Fbar_p(T) exactly when
// gcd(Q,Gamma) = 1, which gives transitivity. If in addition the discriminant
// Delta(u) = disc_Y(Gamma + u*Q) is squarefree of degree 2n'-2, every branch point is
// simple with a distinct branch value, so every inertia generator is a transposition;
// a transitive subgroup of S_n generated by transpositions is S_n.
#include <NTL/ZZ_pX.h>
#include <NTL/ZZ_pXFactoring.h>
#include <cstdio>
#include <cstdlib>
#include <map>
#include <set>
#include <vector>
using namespace NTL; using namespace std;

int main(int argc, char** argv) {
  long p=atol(argv[1]), A=atol(argv[2]), B=atol(argv[3]), hex=atol(argv[4]);
  vector<long> rs, ds;
  { const char* s=argv[5]; long v=0; for(const char* q=s;;q++){ if(*q>='0'&&*q<='9')v=v*10+(*q-'0');
      else{ if(v)rs.push_back(v); v=0; if(!*q)break; } } }
  { const char* s=argv[6]; long v=0; for(const char* q=s;;q++){ if(*q>='0'&&*q<='9')v=v*10+(*q-'0');
      else{ if(v)ds.push_back(v); v=0; if(!*q)break; } } }
  ZZ_p::init(conv<ZZ>(p));
  printf("# monodromy certificate  p=%ld A=%ld B=%ld %s\n",p,A,B,hex?"hexagon":"box");
  printf("# %-3s %-6s %-4s %-9s %-9s %-4s %-9s %-9s %s\n",
         "r","n'","d","gcd(Q,G)","Q sqfree","del","deg Delta","Delta sqfr","monodromy");
  fflush(stdout);

  for (long r : rs) {
    map<long,long> low; bool ok=true;
    for(long e=-B;e<=B&&ok;e++)for(long l=-B;l<=B&&ok;l++){
      if(hex&&labs(e+l)>B)continue;
      long x=((((e%p)*(A%p))%p+(l%p))%p+p)%p, lv=((l%p)+p)%p;
      auto it=low.find(x); if(it!=low.end()&&it->second!=lv)ok=false; else low[x]=lv; }
    if(!ok){printf("  r=%ld not injective\n",r);continue;}
    long A2=MulMod(A%p,A%p,p),den=((1-A2)%p+p)%p;
    long c1=(r>=3&&den)?InvMod(den,p):0,u=r-1;
    map<long,long> qv;
    for(auto&kv:low){ long x=kv.first,lv=kv.second; if(!x)continue;
      long y=PowerMod(x,r,p);
      long vv=MulMod(SubMod(lv,MulMod(x,c1,p),p),InvMod(PowerMod(x,u,p),p),p);
      auto jt=qv.find(y); if(jt!=qv.end()&&jt->second!=vv){ok=false;break;} qv[y]=vv; }
    if(!ok){printf("  r=%ld fold inconsistent\n",r);continue;}
    long n=qv.size();
    vec_ZZ_p xs,ys; xs.SetLength(n); ys.SetLength(n);
    { long i=0; for(auto&kv:qv){xs[i]=conv<ZZ_p>(kv.first);ys[i]=conv<ZZ_p>(kv.second);i++;} }
    ZZ_pX Q=interpolate(xs,ys),G0; BuildFromRoots(G0,xs);

    for (long d : ds) {
      long np=((n+d-1)/d)*d;
      ZZ_pX G=G0; { long extra=np-n,cand=1;
        while(extra>0){ if(!qv.count(cand)){ ZZ_pX lin; SetX(lin); lin-=conv<ZZ_p>(cand); G*=lin; extra--; } cand++; } }
      long dg = deg(GCD(Q,G));
      long qsf = (deg(GCD(Q,diff(Q)))==0);
      // Delta(u) = disc_Y(G + u*Q), degree <= 2*np-2: interpolate from 2*np-1 samples
      long M = 2*np-1;
      vec_ZZ_p us, vs; us.SetLength(M); vs.SetLength(M);
      for (long t=0;t<M;t++){
        ZZ_p ut = conv<ZZ_p>(t);
        ZZ_pX F = G + ut*Q;              // monic of degree np
        ZZ_pX Fd = diff(F);
        us[t]=ut; vs[t]=resultant(F,Fd);
      }
      ZZ_pX Delta = interpolate(us,vs);
      long dD = deg(Delta);
      long dsf = (dD>=0) && (deg(GCD(Delta,diff(Delta)))==0);
      long delta = np - deg(Q);
      long expect = 2*np - 2 - (delta - 1);
      bool full = (dg==0) && qsf && dsf && (dD==expect) && (delta<=2);
      printf("  %-3ld %-6ld %-4ld %-9ld %-9s %-4ld %-9ld %-9s %s\n", r, np, d, dg,
             qsf?"yes":"no", delta, dD, dsf?"yes":"no",
             full ? "S_n" : (dg? "reducible (obstructed)"
                               : (dD!=expect ? "branch count off" : "fails")));
      fflush(stdout);
    }
  }
  return 0;
}
